import{_ as t,o as r,c as n,O as a}from"./chunks/framework.57749cb7.js";const h=JSON.parse('{"title":"异常、IO 与反射","description":"配套知识点：02 Java 核心特性","frontmatter":{"description":"配套知识点：02 Java 核心特性"},"headers":[],"relativePath":"interview/后端/Java/03-异常IO与反射.md","filePath":"interview/后端/Java/03-异常IO与反射.md","lastUpdated":1793242670000}'),e={name:"interview/后端/Java/03-异常IO与反射.md"};function s(l,o,i,g,c,p){return r(),n("div",null,o[0]||(o[0]=[a('<h1 id="异常、io-与反射" tabindex="-1">异常、IO 与反射 <a class="header-anchor" href="#异常、io-与反射" aria-label="Permalink to &quot;异常、IO 与反射&quot;">​</a></h1><blockquote><p>配套知识点：<a href="./../../../backend/Java/02-java核心特性">02 Java 核心特性</a></p></blockquote><blockquote><p><strong>怎么用这份笔记</strong></p><ul><li>分级：<code>★★★ 必须吃透</code> / <code>★★☆ 了解即可（记结论就行）</code> / <code>★☆☆ 可以跳过（一句话看一眼）</code></li><li>【简历亮点，高频追问】：简历里写过的技术，面试官会顺着往下挖，这段必须能展开讲</li><li>每个考点按「定义 → 原理 → 要点 / 易错点」组织，只讲知识点</li></ul></blockquote><hr><h2 id="_1-反射-★★★" tabindex="-1">1. 反射 ★★★ <a class="header-anchor" href="#_1-反射-★★★" aria-label="Permalink to &quot;1. 反射 ★★★&quot;">​</a></h2><p>反射是运行时获取<strong>类的结构</strong>（构造器、字段、方法、注解）并调用它，<strong>绕开编译期的类型检查</strong>。这是框架的基础：<strong>Spring 建 Bean</strong>、<strong>MyBatis 做结果映射</strong>都依赖它。</p><ul><li>代价有两个：<strong>慢</strong>，因为要<strong>动态解析</strong>并做<strong>安全检查</strong>；以及<strong>破坏封装</strong>，能拿到私有成员。</li><li>工程上的优化：启动阶段一次性完成反射并<strong>缓存</strong>结果，<strong>运行期不做反射</strong>；<code>setAccessible(true)</code> 关闭安全检查能提升速度；需要高频创建实例时可用 <strong>ReflectASM</strong> 这类字节码生成方案。</li><li>插件化是典型用法：给各厂商的<strong>命令实现类</strong>加自定义注解，启动时按<strong>包扫描</strong>把所有带注解的类扫出来，反射实例化后按「<strong>协议类型 + 命令字</strong>」注册进<strong>命令表</strong>。这样新增一条指令只要写一个带注解的类，不必改动<strong>核心链路</strong>。</li></ul><hr><h2 id="_2-注解与自定义注解-★★★-【简历亮点-高频追问】" tabindex="-1">2. 注解与自定义注解 ★★★ 【简历亮点，高频追问】 <a class="header-anchor" href="#_2-注解与自定义注解-★★★-【简历亮点-高频追问】" aria-label="Permalink to &quot;2. 注解与自定义注解 ★★★ 【简历亮点，高频追问】&quot;">​</a></h2><p>注解是贴在类、方法、字段上的<strong>标签</strong>，<strong>本身不改变逻辑</strong>，必须由外部读取才生效：运行期靠<strong>反射</strong>读，编译期靠<strong>注解处理器</strong>读（<strong>Lombok</strong> 就是后者）。</p><ul><li><code>@Retention</code> 决定注解保留到哪一步，只有 <strong>RUNTIME</strong> 的才能在运行期通过反射拿到；<code>@Target</code> 限定它可以标注的位置。两者是自定义注解的<strong>固定搭配</strong>。</li><li><strong>注解 + 切面（AOP）</strong> 是最常见的落地方式：横切逻辑集中在切面里，业务代码只加一行注解，新增功能不用改业务代码。典型用途：协议命令行按注解<strong>自动注册</strong>、<code>@RepeatSubmit</code> 防重复提交、基于注解的<strong>限流</strong>、统一<strong>鉴权</strong>。</li></ul><hr><h2 id="_3-异常体系-try-with-resources-★★★" tabindex="-1">3. 异常体系 / try-with-resources ★★★ <a class="header-anchor" href="#_3-异常体系-try-with-resources-★★★" aria-label="Permalink to &quot;3. 异常体系 / try-with-resources ★★★&quot;">​</a></h2><p>根是 <strong>Throwable</strong>，下面分两支：</p><ul><li><strong>Error</strong>：JVM 级故障，比如 OOM，程序本身修不了，<strong>不捕获</strong>。</li><li><strong>Exception</strong>，又分<strong>受检</strong>与<strong>非受检</strong>： <ul><li><strong>受检异常</strong>：编译期强制处理，要么 <code>throws</code> 声明，要么 <code>try-catch</code> 捕获，否则编译不通过，如 <strong>IOException</strong>；通常是调用方能预判、能恢复的情况。</li><li><strong>非受检异常</strong>（<strong>RuntimeException</strong> 及子类）：编译器不检查，如 <strong>NPE</strong>；一般是<strong>编程错误</strong>，应该改代码而不是到处捕获。</li></ul></li></ul><p>另外两个要点：</p><ul><li><strong>finally 一定执行</strong>，除非执行了 <code>System.exit</code>。</li><li><strong>try-with-resources</strong> 可以自动关闭资源，比在 finally 里手写关闭更安全。</li></ul><p>自定义异常统一继承 <strong>RuntimeException</strong>，避免 <code>throws</code> 沿<strong>全链路污染</strong>。捕获的位置放在<strong>系统边界</strong>：Controller、消息消费者（如 Kafka）、定时任务，统一记日志并转成友好响应。设备报文场景下，单个报文解析失败只丢弃这一条，不能让整条连接挂掉，所以每条报文的处理入口都要单独做<strong>异常兜底</strong>。</p><hr><h2 id="_4-什么时候抛、什么时候捕获-throw-vs-throws-★★☆" tabindex="-1">4. 什么时候抛、什么时候捕获 / throw vs throws ★★☆ <a class="header-anchor" href="#_4-什么时候抛、什么时候捕获-throw-vs-throws-★★☆" aria-label="Permalink to &quot;4. 什么时候抛、什么时候捕获 / throw vs throws ★★☆&quot;">​</a></h2><ul><li><strong>能处理就捕获</strong>：能<strong>重试</strong>、能<strong>降级</strong>、能记日志补偿的，在本地处理掉，比如下游调用失败后<strong>重试 + 降级返回</strong>。</li><li><strong>处理不了就往上抛</strong>：或者调用方需要知道结果的情况（<strong>参数校验失败</strong>、设备不存在这类），直接抛<strong>业务异常</strong>，由上层统一转成响应。</li><li><strong>throw 与 throws</strong>：<code>throw</code> 是<strong>抛出一个异常对象</strong>（动作），<code>throws</code> 是<strong>声明方法可能抛出什么</strong>（方法签名）。</li><li>原则：<strong>不吞异常</strong>，也不拿异常当<strong>流程控制</strong>；<code>catch</code> 里不能直接 <code>catch (Exception)</code> 然后返回 null，至少要<strong>打日志</strong>，否则问题无从排查。</li></ul><hr><h2 id="_5-final-finally-finalize-已废弃-★★☆" tabindex="-1">5. final / finally（finalize 已废弃）★★☆ <a class="header-anchor" href="#_5-final-finally-finalize-已废弃-★★☆" aria-label="Permalink to &quot;5. final / finally（finalize 已废弃）★★☆&quot;">​</a></h2><p><strong>final / finally / finalize</strong> 三者只是拼写相近，没有语义关系：</p><ul><li><strong>final</strong>：修饰类 → 不能被继承；修饰方法 → 不能被重写；修饰变量 → <strong>引用</strong>不能改（对象内部内容仍可变）。</li><li><strong>finally</strong>：异常处理中一定会执行的那段代码（除非 <code>System.exit</code>），通常用来释放资源。</li><li><strong>finalize</strong>：对象被回收前调用的方法，<strong>JDK 9 起已废弃</strong>。它<strong>执行时机不确定</strong>、可能<strong>延迟 GC</strong>，还能让对象<strong>复活</strong>，不要用它释放资源；释放资源应该用 <strong>try-with-resources</strong> 或 <strong>Cleaner</strong>。</li></ul><p>工程用法：工具类、常量类用 <code>final</code> 修饰，防止被继承破坏；<strong>处理器基类</strong>被各厂商子类继承时，把基类里的<strong>编解码主流程</strong>声明为 <code>final</code>，只开放子类实现业务方法，保证流程一致、不被改坏。</p><hr><h2 id="_6-字节码-jdk-jre-jvm-★★★" tabindex="-1">6. 字节码 / JDK-JRE-JVM ★★★ <a class="header-anchor" href="#_6-字节码-jdk-jre-jvm-★★★" aria-label="Permalink to &quot;6. 字节码 / JDK-JRE-JVM ★★★&quot;">​</a></h2><ul><li><strong>字节码</strong>：源码用 <code>javac</code> 编译成 <strong>字节码</strong>（<code>.class</code>），由 <strong>JVM</strong> 负责执行。字节码与<strong>平台无关</strong>，各平台 JVM 负责翻译执行，所以是「<strong>一次编译，到处运行</strong>」。</li><li><strong>JIT</strong>：运行期把<strong>热点字节码</strong>编译成<strong>本地机器码</strong>，这是 Java 性能的关键。</li><li><strong>包含关系</strong>：<strong>JDK ⊃ JRE ⊃ JVM</strong>。JVM 负责跑；JRE = JVM + <strong>核心类库</strong>；JDK 在 JRE 之上再加<strong>编译器</strong>等开发工具。</li></ul><p>部署上常见<strong>多阶段构建</strong>：构建阶段用 <strong>JDK</strong>（例如 JDK 21 编译），运行镜像只放 <strong>JRE</strong>，以此<strong>减小镜像体积</strong>。上层能力（<strong>AOP 代理</strong>、协议插件的<strong>动态注册</strong>）都建立在字节码这一层之上。</p><hr><h2 id="_7-bio-nio-aio-★★★-【简历亮点-高频追问】" tabindex="-1">7. BIO / NIO / AIO ★★★ 【简历亮点，高频追问】 <a class="header-anchor" href="#_7-bio-nio-aio-★★★-【简历亮点-高频追问】" aria-label="Permalink to &quot;7. BIO / NIO / AIO ★★★ 【简历亮点，高频追问】&quot;">​</a></h2><ul><li><strong>BIO</strong>：<strong>一连接一线程</strong>，读写都阻塞，线程数随连接数线性增长，扛不住高并发。</li><li><strong>NIO</strong>：<strong>同步非阻塞 + 多路复用</strong>，一个线程用 <strong>Selector</strong> 管理大量连接，谁有事件就处理谁；底层依赖 Linux 的 <strong>epoll</strong>。</li><li><strong>AIO</strong>：<strong>异步</strong>，读写完成后由内核<strong>回调通知</strong>；但 Linux 上实现不成熟（本质仍是 epoll 模拟），<strong>跨平台一致性</strong>不如 NIO。</li></ul><p>NIO 的三大件：<strong>Buffer</strong>（缓冲区）、<strong>Channel</strong>（双向通道）、<strong>Selector</strong>（多路复用器）。</p><p>选型依据：</p><ul><li><strong>设备长连接</strong>场景（大量 TCP 连接常驻）选 <strong>Netty</strong>，本质是 NIO 封装：设备量上去以后 BIO 的一连接一线程撑不住；AIO 在 Linux 上不成熟，所以不用。</li><li>Netty 的 <strong>ChannelHandler 链路</strong>能把<strong>编解码</strong>、心跳、鉴权拆成独立 handler，职责清晰、便于组合复用。</li></ul><hr><h2 id="_8-optional-java-8-新特性-★★★" tabindex="-1">8. Optional / Java 8 新特性 ★★★ <a class="header-anchor" href="#_8-optional-java-8-新特性-★★★" aria-label="Permalink to &quot;8. Optional / Java 8 新特性 ★★★&quot;">​</a></h2><ul><li><strong>Optional</strong> 是包装「<strong>可能为空的值</strong>」的容器，把「<strong>可能没值</strong>」这件事在<strong>方法签名</strong>上显式表达出来。</li><li><code>orElse</code> 无论有没有值<strong>都会计算</strong>参数，<code>orElseGet</code> 才是<strong>惰性</strong>求值；兜底逻辑有开销时必须用 <code>orElseGet</code>。</li><li>使用范围：只建议当<strong>方法返回值</strong>（例如单对象查询这类可能查不到的场景），<strong>不当字段、不当参数</strong>，否则只会增加复杂度。</li><li>同批的 Java 8 新特性：<strong>Stream</strong>、<strong>新时间 API</strong>（<code>LocalDateTime</code> 等）、<strong>CompletableFuture</strong> 是最常用的三块。</li></ul><hr><h2 id="_9-深拷贝浅拷贝-serialversionuid-★★☆" tabindex="-1">9. 深拷贝浅拷贝 / serialVersionUID ★★☆ <a class="header-anchor" href="#_9-深拷贝浅拷贝-serialversionuid-★★☆" aria-label="Permalink to &quot;9. 深拷贝浅拷贝 / serialVersionUID ★★☆&quot;">​</a></h2><ul><li><strong>浅拷贝</strong>：只复制对象本身，内部的<strong>引用字段</strong>仍指向<strong>同一个对象</strong>，两个对象共享引用。</li><li><strong>深拷贝</strong>：把<strong>引用链</strong>上的对象全部复制一份，彼此完全独立。</li><li><code>clone()</code> 默认是<strong>浅拷贝</strong>；要深拷贝可以覆写 <code>clone</code> 逐层复制，或者直接用<strong>序列化 / 反序列化</strong>做拷贝。</li></ul><p><strong>serialVersionUID</strong> 是<strong>序列化版本号</strong>：</p><ul><li>不显式声明时由编译器按类结构生成，类一改动（加字段、改方法）值就会变，旧数据<strong>反序列化失败</strong>。</li><li>跨服务传输的 DTO 应<strong>显式声明</strong> <code>serialVersionUID</code>，避免加个字段就造成<strong>反序列化不兼容</strong>。</li><li>需要对象快照又不想手写 <code>clone</code> 时，可以直接用<strong>序列化拷贝</strong>实现深拷贝。</li></ul><hr><h2 id="_10-collection-与-collections-的区别-★★☆" tabindex="-1">10. Collection 与 Collections 的区别 ★★☆ <a class="header-anchor" href="#_10-collection-与-collections-的区别-★★☆" aria-label="Permalink to &quot;10. Collection 与 Collections 的区别 ★★☆&quot;">​</a></h2><p>一句话：<strong>Collection 是接口，Collections 是工具类</strong>（多一个 s）。</p><ul><li><strong>Collection</strong>：<code>List</code> / <code>Set</code> / <code>Queue</code> 的<strong>父接口</strong>，定义集合的<strong>基本能力</strong>——<code>add</code>、<code>remove</code>、<code>size</code>、<code>iterator</code>。</li><li><strong>Collections</strong>：全是<strong>静态方法</strong>的工具类，用来操作或包装集合：<code>sort</code>、<code>reverse</code>、<code>shuffle</code>、<code>max/min</code>、<code>binarySearch</code>、<code>synchronizedXxx</code>（同步包装）、<code>unmodifiableXxx</code>（不可变包装）、<code>emptyList</code>。</li><li>常用写法：返回空结果时用 <code>Collections.emptyList()</code> 而不是 <code>null</code>，调用方少一层判空；<code>synchronizedList</code> 包装需要<strong>多线程写</strong>的列表；<code>unmodifiableList</code> 在把内部配置列表<strong>暴露出去</strong>时防止外部修改。</li><li>易错点：<code>Collections.sort</code> 要求元素<strong>实现 <code>Comparable</code></strong>，或者显式传入 <code>Comparator</code>，否则抛 <strong>ClassCastException</strong>；空集合场景<strong>不要返回 null</strong>，用 <code>emptyList</code> 能让调用方少写判空。</li></ul><hr><h2 id="附-原始题库-旧版逐题-与上文重叠-可折叠跳过" tabindex="-1">附：原始题库（旧版逐题，与上文重叠，可折叠跳过） <a class="header-anchor" href="#附-原始题库-旧版逐题-与上文重叠-可折叠跳过" aria-label="Permalink to &quot;附：原始题库（旧版逐题，与上文重叠，可折叠跳过）&quot;">​</a></h2><details class="details custom-block"><summary>展开查看原始题库</summary><h3 id="_11-深拷贝和浅拷贝的区别是什么" tabindex="-1">11. 深拷贝和浅拷贝的区别是什么? <a class="header-anchor" href="#_11-深拷贝和浅拷贝的区别是什么" aria-label="Permalink to &quot;11. 深拷贝和浅拷贝的区别是什么?&quot;">​</a></h3><p>浅拷贝:被复制对象的所有变量都含有与原来的对象相同的值,而所有的对其他对象的引用仍然指向原来的对象.换言之,浅拷贝仅仅复制所考虑的对象,而不复制它所引用的对象.</p><p>深拷贝:被复制对象的所有变量都含有与原来的对象相同的值.而那些引用其他对象的变量将指向被复制过的新对象.而不再是原有的那些被引用的对象.换言之.深拷贝把要复制的对象所引用的对象都复制了一遍.</p><h3 id="_12-try-catch-finally-try里有return-finally还执行么" tabindex="-1">12. try catch finally，try里有return，finally还执行么？ <a class="header-anchor" href="#_12-try-catch-finally-try里有return-finally还执行么" aria-label="Permalink to &quot;12. try catch finally，try里有return，finally还执行么？&quot;">​</a></h3><p>执行，并且finally的执行早于try里面的return</p><p>结论：</p><p>1、不管有木有出现异常，finally块中代码都会执行；</p><p>2、当try和catch中有return时，finally仍然会执行；</p><p>3、finally是在return后面的表达式运算后执行的（此时并没有返回运算后的值，而是先把要返回的值保存起来，管finally中的代码怎么样，返回的值都不会改变，任然是之前保存的值），所以函数返回值是在finally执行前确定的；</p><p>4、finally中最好不要包含return，否则程序会提前退出，返回值不是try或catch中保存的返回值。</p><h3 id="_13-exception与error包结构" tabindex="-1">13. Exception与Error包结构 <a class="header-anchor" href="#_13-exception与error包结构" aria-label="Permalink to &quot;13. Exception与Error包结构&quot;">​</a></h3><p>Java可抛出(Throwable)的结构分为三种类型：被检查的异常(CheckedException)，运行时异常 (RuntimeException)，错误(Error)。</p><p>1、运行时异常</p><p>定义:RuntimeException及其子类都被称为运行时异常。</p><p>特点:Java编译器不会检查它。也就是说，当程序中可能出现这类异常时，倘若既&quot;没有通过throws 声明抛出它&quot;，也&quot;没有用try-catch语句捕获它&quot;，还是会编译通过。例如，除数为零时产生的</p><p>ArithmeticException异常，数组越界时产生的IndexOutOfBoundsException异常，fail-fast机制产</p><p>生的ConcurrentModificationException异常（java.util包下面的所有的集合类都是快速失败</p><p>的， “快速失败”也就是fail-fast，它是Java集合的一种错误检测机制。当多个线程对集合进行结构上的改变的操作时，有可能会产生fail-fast机制。记住是有可能，而不是一定。例如：假设存在两个线</p><p>程（线程1、线程2），线程1通过Iterator在遍历集合A中的元素，在某个时候线程2修改了集合A的结构（是结构上面的修改，而不是简单的修改集合元素的内容），那么这个时候程序就会抛出</p><p>ConcurrentModificationException 异常，从而产生fail-fast机制，这个错叫并发修改异常。 Fail- safe，java.util.concurrent包下面的所有的类都是安全失败的，在遍历过程中，如果已经遍历的数组上的内容变化了，迭代器不会抛出ConcurrentModificationException异常。如果未遍历的数组上的内容发生了变化，则有可能反映到迭代过程中。这就是ConcurrentHashMap迭代器弱一致的表现。 ConcurrentHashMap的弱一致性主要是为了提升效率，是一致性与效率之间的一种权衡。 要成为强一致性，就得到处使用锁，甚至是全局锁，这就与Hashtable和同步的HashMap一样</p><p>了。）等，都属于运行时异常。</p><p>常见的五种运行时异常：</p><p>ClassCastException（类转换异常）</p><p>IndexOutOfBoundsException（数组越界）</p><p>NullPointerException（空指针异常）</p><p>ArrayStoreException（数据存储异常，操作数组是类型不一致）</p><p>BufferOverflowException</p><p>2、被检查异常</p><p>定义:Exception类本身，以及Exception的子类中除了&quot;运行时异常&quot;之外的其它子类都属于被检查异常。</p><p>特点 : Java编译器会检查它。 此类异常，要么通过throws进行声明抛出，要么通过try-catch进行捕获处理，否则不能通过编译。例如，CloneNotSupportedException就属于被检查异常。当通过</p><p>clone()接口去克隆一个对象，而该对象对应的类没有实现Cloneable接口，就会抛出</p><p>CloneNotSupportedException异常。被检查异常通常都是可以恢复的。 如：</p><p>IOException</p><p>FileNotFoundException</p><p>SQLException</p><p>被检查的异常适用于那些不是因程序引起的错误情况，比如：读取文件时文件不存在引发的</p><p>FileNotFoundException。然而，不被检查的异常通常都是由于糟糕的编程引起的，比如：在对象引用时没有确保对象非空而引起的 NullPointerException。</p><p>3、错误</p><p>定义 : Error类及其子类。</p><p>特点 : 和运行时异常一样，编译器也不会对错误进行检查。</p><p>当资源不足、约束失败、或是其它程序无法继续运行的条件发生时，就产生错误。程序本身无法修复这些错误的。例如，VirtualMachineError就属于错误。出现这种错误会导致程序终止运行。</p><p>OutOfMemoryError、ThreadDeath。</p><p>Java虚拟机规范规定JVM的内存分为了好几块，比如堆，栈，程序计数器，方法区等</p><h3 id="_14-java-序列化中如果有些字段不想进行序列化-怎么办" tabindex="-1">14. Java 序列化中如果有些字段不想进行序列化，怎么办？ <a class="header-anchor" href="#_14-java-序列化中如果有些字段不想进行序列化-怎么办" aria-label="Permalink to &quot;14. Java 序列化中如果有些字段不想进行序列化，怎么办？&quot;">​</a></h3><p>对于不想进行序列化的变量，使用 transient 关键字修饰。</p><p>transient 关键字的作用是：阻止实例中那些用此关键字修饰的的变量序列化；当对象被反序列化时，被 transient 修饰的变量值不会被持久化和恢复。transient 只能修饰变量，不能修饰类和方法。</p><h3 id="_15-说说java-中-io-流" tabindex="-1">15. 说说Java 中 IO 流 <a class="header-anchor" href="#_15-说说java-中-io-流" aria-label="Permalink to &quot;15. 说说Java 中 IO 流&quot;">​</a></h3><p>Java 中 IO 流分为几种?</p><p>按照流的流向分，可以分为输入流和输出流；</p><p>按照操作单元划分，可以划分为字节流和字符流；</p><p>按照流的角色划分为节点流和处理流。</p><p>Java Io 流共涉及 40 多个类，这些类看上去很杂乱，但实际上很有规则，而且彼此之间存在非常紧密的联系， Java I0 流的 40 多个类都是从如下 4 个抽象类基类中派生出来的。</p><p>InputStream/Reader: 所有的输入流的基类，前者是字节输入流，后者是字符输入流。 OutputStream/Writer: 所有输出流的基类，前者是字节输出流，后者是字符输出流。</p><p>按操作方式分类结构图：</p><p><img src="https://raw.githubusercontent.com/caolinchao2/blogimg/main/img/image25.png" alt="说说Java 中 IO 流"></p><p><img src="https://raw.githubusercontent.com/caolinchao2/blogimg/main/img/image26.png" alt="说说Java 中 IO 流"></p><p>按操作对象分类结构图：</p><p><img src="https://raw.githubusercontent.com/caolinchao2/blogimg/main/img/image27.jpeg" alt="说说Java 中 IO 流"></p><h3 id="_16-java-io与-nio的区别-补充" tabindex="-1">16. Java IO与 NIO的区别（补充） <a class="header-anchor" href="#_16-java-io与-nio的区别-补充" aria-label="Permalink to &quot;16. Java IO与 NIO的区别（补充）&quot;">​</a></h3><p>NIO即New IO，这个库是在JDK1.4中才引入的。 NIO和IO有相同的作用和目的，但实现方式不同， NIO主要用到的是块，所以NIO的效率要比IO高很多。在Java API中提供了两套NIO，一套是针对标准输入输出NIO，另一套就是网络编程NIO。</p><h3 id="_17-java反射的作用与原理" tabindex="-1">17. java反射的作用与原理 <a class="header-anchor" href="#_17-java反射的作用与原理" aria-label="Permalink to &quot;17. java反射的作用与原理&quot;">​</a></h3><p>1、定义：</p><p>反射机制是在运行时，对于任意一个类，都能够知道这个类的所有属性和方法；对于任意个对象， 都能够调用它的任意一个方法。在java中，只要给定类的名字，就可以通过反射机制来获得类的所有信息。</p><p>I 这种动态获取的信息以及动态调用对象的方法的功能称为Java语言的反射机制。</p><p>2、哪里会用到反射机制？</p><p>jdbc就是典型的反射</p><p>这就是反射。如hibernate，struts等框架使用反射实现的。</p><p>3、反射的实现方式：</p><p>第一步：获取Class对象，有4中方法： 1）Class.forName(“类的路径”)；2）类名.class 3）对象名.getClass() 4）基本类型的包装类，可以调用包装类的Type属性来获得该包装类的Class对象</p><p>4、实现Java反射的类：</p><p>1）Class：表示正在运行的Java应用程序中的类和接口注意： 所有获取对象的信息都需要Class类来实现。 2）Field：提供有关类和接口的属性信息，以及对它的动态访问权限。 3）Constructor： 提供关于类的单个构造方法的信息以及它的访问权限 4）Method：提供类或接口中某个方法的信息</p><p>5、反射机制的优缺点：</p><p>优点： 1）能够运行时动态获取类的实例，提高灵活性； 2）与动态编译结合缺点： 1）使用反射性能较低，需要解析字节码，将内存中的对象进行解析。 解决方案： 1、通过setAccessible(true) 关闭JDK的安全检查来提升反射速度； 2、多次创建一个类的实例时，有缓存会快很多 3、</p><p>ReflectASM工具类，通过字节码生成的方式加快反射速度 2）相对不安全，破坏了封装性（因为通过反射可以获得私有方法和属性）</p><h3 id="_18-获取一个类class对象的方式有哪些" tabindex="-1">18. 获取一个类Class对象的方式有哪些？ <a class="header-anchor" href="#_18-获取一个类class对象的方式有哪些" aria-label="Permalink to &quot;18. 获取一个类Class对象的方式有哪些？&quot;">​</a></h3><p>搞清楚类对象和实例对象，但都是对象。</p><p>第一种：通过类对象的 getClass() 方法获取，细心点的都知道，这个 getClass 是 Object 类里面的方法。</p><p>第二种：通过类的静态成员表示，每个类都有隐含的静态成员 class。</p><p>第三种：通过 Class 类的静态方法 forName() 方法获取。</p><h3 id="_19-说说你平时是怎么处理-java-异常的" tabindex="-1">19. 说说你平时是怎么处理 Java 异常的 <a class="header-anchor" href="#_19-说说你平时是怎么处理-java-异常的" aria-label="Permalink to &quot;19. 说说你平时是怎么处理 Java 异常的&quot;">​</a></h3><p>try-catch-finally</p><p>try 块负责监控可能出现异常的代码</p><p>catch 块负责捕获可能出现的异常，并进行处理</p><p>finally 块负责清理各种资源，不管是否出现异常都会执行</p><p>其中 try 块是必须的，catch 和 finally 至少存在一个标准异常处理流程</p><p><img src="https://raw.githubusercontent.com/caolinchao2/blogimg/main/img/image47.png" alt="说说你平时是怎么处理 Java 异常的"></p><p>抛出异常→捕获异常→捕获成功（当 catch 的异常类型与抛出的异常类型匹配时，捕获成功） →异常被处理，程序继续运行抛出异常→捕获异常→捕获失败（当 catch 的异常类型与抛出异常类型不匹配时，捕获失败） →异常未被处理，程序中断运行</p><p>在开发过程中会使用到自定义异常，在通常情况下，程序很少会自己抛出异常，因为异常的类名通常也包含了该异常的有用信息，所以在选择抛出异常的时候，应该选择合适的异常类，从而可以明确地描述该异常情况，所以这时候往往都是自定义异常。</p><p>自定义异常通常是通过继承 java.lang.Exception 类，如果想自定义 Runtime 异常的话，可以继承 java.lang.RuntimeException 类，实现一个无参构造和一个带字符串参数的有参构造方法。</p><p>在业务代码里，可以针对性的使用自定义异常。比如说：该用户不具备某某权限、余额不足等。</p><h3 id="_20-说说深拷贝和浅拷贝" tabindex="-1">20. 说说深拷贝和浅拷贝？ <a class="header-anchor" href="#_20-说说深拷贝和浅拷贝" aria-label="Permalink to &quot;20. 说说深拷贝和浅拷贝？&quot;">​</a></h3><p>浅拷贝（shallowCopy）只是增加了一个指针指向已存在的内存地址，</p><p>深拷贝（deepCopy）是增加了一个指针并且申请了一个新的内存，使这个增加的指针指向这个新的内存，</p><p>使用深拷贝的情况下，释放内存的时候不会因为出现浅拷贝时释放同一个内存的错误。</p><p>最好是结合克隆已经原型模式联系在一起哈，记得复习的时候，把这几个联系起来的。</p><p>I 欢迎关注微信公众号：Java后端技术全栈</p></details><h2 id="附-一句话速记-可以跳过-★☆☆" tabindex="-1">附：一句话速记（可以跳过 ★☆☆） <a class="header-anchor" href="#附-一句话速记-可以跳过-★☆☆" aria-label="Permalink to &quot;附：一句话速记（可以跳过 ★☆☆）&quot;">​</a></h2><ul><li><strong>异常体系</strong>：Throwable → Error（不该捕获）/ Exception（受检 + 运行时）。</li><li><strong>try-with-resources</strong>：实现 AutoCloseable 即可自动关闭，比 finally 更安全。</li><li><strong>final / finally / finalize</strong>：finalize 已废弃（JDK9 起 @Deprecated），别再用。</li><li><strong>BIO / NIO / AIO</strong>：阻塞流 / 多路复用（Selector）/ 异步回调。</li><li><strong>反射</strong>：Class → Constructor / Method / Field，能拿到私有成员；Spring、MyBatis 全靠它。</li><li><strong>深拷贝</strong>：基本类型值拷贝、引用类型要递归克隆；浅拷贝只复制引用。</li><li><strong>serialVersionUID</strong>：不显式声明时反序列化容易 InvalidClassException；transient 字段不参与序列化。</li></ul>',53)]))}const u=t(e,[["render",s]]);export{h as __pageData,u as default};
